diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..5a6d071 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,49 @@ export interface Record {
   warns: readonly string[];
 }

+const extractSemanticFingerprint = (text: string): string => {
+  const themes = new Set<string>();
+  const lower = text.toLowerCase();
+
+  if (/\b(ops|operational|infrastructure|operate|maintain|run|managed)\b/.test(lower)) {
+    themes.add('ops_burden');
+  }
+  if (/\b(stateful|persistent|always.on|ongoing|state)\b/.test(lower)) {
+    themes.add('always_on');
+  }
+  if (/\b(service|component|tier|system)\b/.test(lower)) {
+    themes.add('component');
+  }
+
+  return Array.from(themes).sort().join('|');
+};
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
+  const seenFingerprints = new Set<string>();
+
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of record.ruledOut) {
+      const fp = extractSemanticFingerprint(entry);
+      if (!seenFingerprints.has(fp)) {
+        lines.push(`- ruled out: ${entry}`);
+        seenFingerprints.add(fp);
+      }
+    }
+    for (const limit of record.limits) {
+      const fp = extractSemanticFingerprint(limit);
+      if (!seenFingerprints.has(fp)) {
+        lines.push(`- limit: ${limit}`);
+        seenFingerprints.add(fp);
+      }
+    }
+    for (const warn of record.warns) {
+      const fp = extractSemanticFingerprint(warn);
+      if (!seenFingerprints.has(fp)) {
+        lines.push(`- warn: ${warn}`);
+        seenFingerprints.add(fp);
+      }
+    }
   }
   return lines.join("\n");
 };
